  const name = clean(url.searchParams.get('name'), 16, 'Wanderer');
  const c = { socket, id: crypto.randomBytes(4).toString('hex'), alive: true, buf: Buffer.alloc(0), budget: 40, last: Date.now(),
    p: { name, x: 0, y: 0, z: 0, yaw: 0, lv: 1, state: 'alive' } };
  c.p.id = c.id;
  c.send = obj => { if (!socket.destroyed) { const f = frame(1, Buffer.from(JSON.stringify(obj))); if (f) socket.write(f); } };
  c.close = () => { if (!socket.destroyed) { try { socket.end(frame(8, Buffer.alloc(0))); } catch {} } };

  if (!rooms.has(code)) rooms.set(code, new Set());
